import{_ as e,c as l,o as i,ag as r}from"./chunks/framework.DPDPlp3K.js";const _=JSON.parse('{"title":"考试冲刺全流程","description":"从考试样卷到可打卡刷题网页的一站式备考工作台。当用户给出考试日期、目标分数/合格线和历年样卷、考试大纲、考试介绍等材料，要求制定复习计划、逐日学习安排、可打卡网页、在线刷题卡片、错题本、或把错题发回分析薄弱知识点时使用。适用于学位英语、四六级、考研、教资、软考、期中期末等任何考试。触发词：备考计划、冲刺计划、复习计划、历年样卷、刷题、做题、错题本、错题分析、打卡、督学、每日任务。","frontmatter":{"name":"exam-sprint-workflow","label":"考试冲刺全流程","description":"从考试样卷到可打卡刷题网页的一站式备考工作台。当用户给出考试日期、目标分数/合格线和历年样卷、考试大纲、考试介绍等材料，要求制定复习计划、逐日学习安排、可打卡网页、在线刷题卡片、错题本、或把错题发回分析薄弱知识点时使用。适用于学位英语、四六级、考研、教资、软考、期中期末等任何考试。触发词：备考计划、冲刺计划、复习计划、历年样卷、刷题、做题、错题本、错题分析、打卡、督学、每日任务。"},"headers":[],"relativePath":"public/skills/exam-sprint-workflow/SKILL.md","filePath":"public/skills/exam-sprint-workflow/SKILL.md"}'),o={name:"public/skills/exam-sprint-workflow/SKILL.md"};function t(s,a,n,d,h,c){return i(),l("div",null,a[0]||(a[0]=[r('<h1 id="考试冲刺全流程" tabindex="-1">考试冲刺全流程 <a class="header-anchor" href="#考试冲刺全流程" aria-label="Permalink to &quot;考试冲刺全流程&quot;">​</a></h1><p>把用户给的考试材料（样卷/大纲/介绍）加工成一个可打卡、可刷题、可反馈调整的在线备考工作台，并承接后续错题分析闭环。整套流程已在一次真实备考（深圳大学学士学位英语，18 天冲刺）中完整跑通。</p><h2 id="硬边界" tabindex="-1">硬边界 <a class="header-anchor" href="#硬边界" aria-label="Permalink to &quot;硬边界&quot;">​</a></h2><ul><li>不押题、不泄题、不承诺分数或通过；官方答案缺失时可以自拟参考答案，但必须显式标注&quot;自拟非官方&quot;。</li><li>考试日期、题型、合格线以用户材料和官方通知为准；无法核验的标 <code>[待确认]</code>，估算值标 <code>[计划假设]</code>，不伪装成已确认事实。</li><li>题库内容必须逐字来自用户提供的材料，解析题目后必须抽查回读核对，不得凭记忆补题。</li></ul><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to &quot;核心流程&quot;">​</a></h2><h3 id="_1-输入核对" tabindex="-1">1. 输入核对 <a class="header-anchor" href="#_1-输入核对" aria-label="Permalink to &quot;1. 输入核对&quot;">​</a></h3><p>最小输入：考试名称、考试日期、可用时间（工作日/休息日各几小时）。缺目标分数时问一句或按合格线假设并标注。材料有多少用多少，没有样卷就只做计划不做题库。</p><h3 id="_2-材料分析-决定策略的关键步骤" tabindex="-1">2. 材料分析（决定策略的关键步骤） <a class="header-anchor" href="#_2-材料分析-决定策略的关键步骤" aria-label="Permalink to &quot;2. 材料分析（决定策略的关键步骤）&quot;">​</a></h3><ul><li>逐份读取用户材料，提取：题型结构、题量、分值、考试时长、官方答题要求。</li><li><strong>逐年交叉对比</strong>：题型是否改版（旧题型素材要拆解使用——还能练的当题库，不再考的明确跳过并在页面标注）。</li><li><strong>重复文件排查</strong>：用 md5 或全文 diff 比对各年样卷文件。同名不同年的文件可能内容完全相同（真实案例：2022-2025 四份样卷实为一套题），必须如实告知用户，避免题库虚胖。</li><li>答案缺失的部分（如翻译、写作范文）如实标注，不虚构官方答案。</li></ul><h3 id="_3-时间与计划计算" tabindex="-1">3. 时间与计划计算 <a class="header-anchor" href="#_3-时间与计划计算" aria-label="Permalink to &quot;3. 时间与计划计算&quot;">​</a></h3><ul><li>用 Python <code>chinese_calendar</code> 计算剩余天数、节假日和调休补班日——不要心算。</li><li>按用户确认的每日可用时间排任务；每天任务总量必须 ≤ 可用时间。</li><li>计划数据落盘为 <code>plan_data.json</code>（字段规范见 <a href="./references/data-schemas.html">references/data-schemas.md</a>）：阶段划分、逐日任务（每个任务带材料/时长/验收标准）、阶段检测阈值、动态调整规则、考试当天时间分配策略。</li></ul><h3 id="_4-题库构建" tabindex="-1">4. 题库构建 <a class="header-anchor" href="#_4-题库构建" aria-label="Permalink to &quot;4. 题库构建&quot;">​</a></h3><ul><li>解析样卷客观题为结构化 <code>questions.json</code>（字段规范见 <a href="./references/data-schemas.html">references/data-schemas.md</a>）：题干、选项、官方答案、考点标签、来源。</li><li>考点标签是学习性标注（如&quot;虚拟语气&quot;&quot;固定搭配&quot;），按知识点归类，供后续错题分析用。</li><li>主观题（翻译/写作）：翻译给参考译文（自拟需标注），用户在页面三档自评（完全正确/部分正确/错误），后两档计错题。</li><li>解析后必须抽查 3-5 题与原文比对，并程序化校验（选项数、答案合法性、题目总数）。</li></ul><h3 id="_5-交付-可打卡刷题网页" tabindex="-1">5. 交付：可打卡刷题网页 <a class="header-anchor" href="#_5-交付-可打卡刷题网页" aria-label="Permalink to &quot;5. 交付：可打卡刷题网页&quot;">​</a></h3><p>调用 app_builder 构建，<code>arch_type=jspage</code>（需要本地状态保存）。页面四层结构：</p><ol><li><strong>打卡层</strong>：今日视图 + 全程计划（阶段分组）+ 任务勾选 + 复盘输入</li><li><strong>刷题层</strong>：按套卷→模块分组，卡片式逐题作答，即时判分、显示考点；完形/阅读先呈现原文；翻译题输入译文自评</li><li><strong>错题本层</strong>：自动汇总错题（我的答案/正确答案/考点/错误次数）+ 重做模式 + <strong>一键导出纯文本</strong>（顶部统计 + 逐题明细，供用户复制发回聊天）</li><li><strong>考情层</strong>：题型结构表、新旧题型差异、提分优先级、检测阈值、调整规则、假设与待确认标注</li></ol><p>用户后续要求改计划/加题时，<strong>原地更新同一应用</strong>（传 target_app_id/target_app_token），保留用户已有打卡数据。</p><h3 id="_6-错题分析闭环-用户发回错题本后" tabindex="-1">6. 错题分析闭环（用户发回错题本后） <a class="header-anchor" href="#_6-错题分析闭环-用户发回错题本后" aria-label="Permalink to &quot;6. 错题分析闭环（用户发回错题本后）&quot;">​</a></h3><p>按 <a href="./references/wrong-book-analysis.html">references/wrong-book-analysis.md</a> 的格式输出：考点分布统计 → 薄弱知识点清单（按错频和提分性价比排序）→ 针对性补弱任务 → 对原计划的调整建议。之后按需更新页面计划数据。</p><h2 id="交付检查" tabindex="-1">交付检查 <a class="header-anchor" href="#交付检查" aria-label="Permalink to &quot;交付检查&quot;">​</a></h2><ul><li>[ ] 每日任务总量 ≤ 用户每日可用时间</li><li>[ ] 样卷改版/重复/答案缺失三项排查都有结论并告知用户</li><li>[ ] 题库题目与原文抽查一致，答案全部来自官方文件（或已标注自拟）</li><li>[ ] 页面含错题本一键导出，导出文本可整段复制</li><li>[ ] 计划中的假设、待确认项在页面和交付说明中都有标注</li></ul>',21)]))}const p=e(o,[["render",t]]);export{_ as __pageData,p as default};
